import designIndex from '../../../oracle/designs/index.json';

// Example designs from Laboratori d'envol, generated by
// scripts/build-designs.ts. Each one is served as
// examples/<id>/leparagliding.txt plus its airfoils.
export interface Design {
  id: string;
  wing: string;
  program: string;
  cells: number;
  airfoils: string[];
  adapted: string;
}

export const DESIGNS: readonly Design[] = designIndex;
